package com.infinifolder.preview

/** Numeric font layout measurements only; no font outlines or glyph data.
 * Generated by scripts/measure-bgi-metrics.py from the referenced RIPterm 1.54 fonts.
 * Font IDs 1..10; metrics retain proportional advances instead of an estimated cell width.
 */
internal object RipFontMetrics {
    private val heights=intArrayOf(31,9,32,32,37,35,31,35,55,60)
    private val advances=listOf(
        // TRIP: reference SHA-256 831963618a5dbf3562e12c3b4b8bab3ed3879143de3c7cd9293be171a44282db
        "",
        // LITT: reference SHA-256 8a6ecee3378830669335c07c661dc8929c25b01a7163b7fdb32d634d074d6b9c
        "",
        // SANS: reference SHA-256 edd4db0e5735ce0872d60137819e2b74a590d069be7585269b7b6d675e319bbc
        "",
        // GOTH: reference SHA-256 8620ae9db9dd874b842f67f7153721a5681fef3cd9e99af0fde41f3b1194f183
        "",
        // SCRI: reference SHA-256 04fde2931ba5392c55791b0c99c0c6790cfae97e9792b5833e40e87e19730bf7
        "",
        // SIMP: reference SHA-256 8d51af7680da29886481166fbc352141e6c615dd97927521b06cb2548f940acf
        "",
        // TSCR: reference SHA-256 305e2a9657902fef2a52b25e398a5e2fca4cd0ace0fc0208704b2cb5c360b187
        "",
        // LCOM: reference SHA-256 69d210b35c0c3e74cb6cfe9062b471579c43f3cf12fcc8c76f63b96235e9d9bb
        "",
        // EURO: reference SHA-256 783392b9fd0414a9c768db7741808811de63c599b34f92acb2d967e74993c6b1
        "",
        // BOLD: reference SHA-256 ee8b45d7491e1bc61936923f8642f1766c58dee7c528fa542e727092a914d07e
        ""
    ).map {hex->IntArray(256){hex.substring(it*2,it*2+2).toInt(16)}}
    fun height(font:Int)=heights[(font-1).coerceIn(0,9)]
    fun advance(font:Int,code:Int)=advances[(font-1).coerceIn(0,9)][code and 255]
}
